{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How do I calculate how much bitumen I need?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Multiply the road length × width × compacted thickness to get the volume, then multiply by the mix density to get total weight. Multiply total weight by the bitumen content percentage (typically 5–7%) to get the bitumen quantity. Our calculator handles all unit conversions automatically."
      }
    },
    {
      "@type": "Question",
      "name": "What is a typical bitumen content for road construction?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "For dense-graded HMA (the most common mix), bitumen content typically ranges from 5.0–6.5% by mass of the total mix. SMA mixes run higher at 6.0–7.5%. Open-graded mixes are usually 5.0–6.0%. The exact optimum is determined by mix design testing per local standards (e.g., Marshall or Superpave methods)."
      }
    },
    {
      "@type": "Question",
      "name": "What density should I use for asphalt?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "For standard dense-graded HMA, use 2300–2400 kg/m³. SMA is typically 2250–2380 kg/m³. Open-graded and porous mixes are lower at 1900–2150 kg/m³. The calculator includes 7 preset mix types with appropriate default densities for each."
      }
    },
    {
      "@type": "Question",
      "name": "What is the difference between bitumen and asphalt?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Bitumen (also called asphalt binder) is the black, viscous petroleum-derived binding agent. Asphalt (or asphalt concrete) is the finished pavement mix that combines bitumen with aggregate (stone, gravel, sand). When people say \"asphalt calculator\" they typically mean calculating the total mixed material weight, which is what this tool does."
      }
    },
    {
      "@type": "Question",
      "name": "How accurate are these estimates?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The formulas are mathematically exact based on your inputs. Accuracy depends on how representative your density and bitumen content values are for your specific mix. For budgeting and early-stage planning, estimates are typically within ±5–10%. For final procurement, always use laboratory-tested mix design values and consult a licensed engineer."
      }
    },
    {
      "@type": "Question",
      "name": "Can I use this calculator for driveways and car parks?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. The calculator works for any bituminous pavement area — from a residential driveway to a motorway. For smaller projects, typical thickness is 40–50 mm for the wearing course. For commercial areas, 50–75 mm is common. Select the appropriate mix type and thickness for your application."
      }
    },
    {
      "@type": "Question",
      "name": "Does the calculator account for waste or compaction factor?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The results represent the compacted in-place material quantity. In practice, you should add a 5–10% wastage factor to your order to account for haulage, spreading losses, and trim edges. For loose material to compacted volume conversion, the compaction factor is already embedded in the density value you enter."
      }
    }
  ]
}

