{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "What is asphalt density in kg/m³?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Use your specified mix density. With an estimating input of 2,400 kg/m³, each cubic metre has a mass of 2,400 kg, or 2.4 metric tonnes. This is an assumption for calculation, not a universal asphalt specification."
      }
    },
    {
      "@type": "Question",
      "name": "Is 145 lb/ft³ the same as 2,400 kg/m³?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. 145 lb/ft³ equals approximately 2,322.68 kg/m³. A density of 2,400 kg/m³ equals approximately 149.83 lb/ft³. Convert the same input when comparing metric and imperial estimates."
      }
    },
    {
      "@type": "Question",
      "name": "How many metric tonnes are in 1 m³ of asphalt?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Divide density in kg/m³ by 1,000. At 2,300 kg/m³, one cubic metre is 2.3 tonnes; at 2,400 kg/m³, it is 2.4 tonnes."
      }
    },
    {
      "@type": "Question",
      "name": "Can I use asphalt density for liquid bitumen?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. A paving mixture and its liquid binder are different materials. Use product-specific bitumen density at the relevant reference temperature for binder volume-to-mass calculations."
      }
    }
  ]
}

