{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How much will a ton of asphalt millings cover at 4 inches?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "At an assumed bulk density of 125 lb/ft³, one US short ton covers 48 square feet at 4 inches. The answer changes with density. Use density and depth for the same loose or compacted material condition."
      }
    },
    {
      "@type": "Question",
      "name": "How many tons of millings do I need for 1,000 square feet?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "At 4 inches and an assumed 125 lb/ft³, 1,000 square feet requires 20.83 US short tons before any project-specific allowance. At 3 inches with the same density, it requires 15.63 short tons."
      }
    },
    {
      "@type": "Question",
      "name": "Can I use one fixed compaction factor for all millings?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. Bulk volume depends on particle grading, moisture and placement. Use measured or supplier-provided densities. Do not add compaction again when your mass calculation already uses compacted depth and compacted density."
      }
    },
    {
      "@type": "Question",
      "name": "Is a ton of millings the same as a cubic yard?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. A ton measures mass and a cubic yard measures volume. At an assumed 125 lb/ft³, a cubic yard weighs 1.6875 US short tons because 27 × 125 ÷ 2,000 = 1.6875."
      }
    }
  ]
}

