{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Is 2 inches of asphalt enough for a driveway?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Thickness alone does not establish suitability. Traffic, subgrade, base, drainage and the specified mix all matter. Ask the pavement designer or qualified installer for a layer design; use a calculator only to estimate its material quantity."
      }
    },
    {
      "@type": "Question",
      "name": "Should I enter loose or compacted asphalt thickness?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "For a finished pavement takeoff, enter compacted thickness and the matching compacted mix density. If estimating loose delivery volume, use density and dimensions for that loose condition instead."
