{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How many tons are in 1 cubic yard of asphalt?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "At an assumed 145 lb/ft³, one cubic yard weighs 1.9575 US short tons, approximately 1.96. It weighs about 1.776 metric tonnes. Use your material-specific bulk density for an order."
      }
    },
    {
      "@type": "Question",
      "name": "How many tons are in 10 cubic yards of asphalt?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Using 145 lb/ft³, 10 cubic yards weigh 19.575 US short tons, or approximately 17.758 metric tonnes. These values exclude any project-specific allowance."
      }
    },
    {
      "@type": "Question",
      "name": "How many cubic yards are in one ton of asphalt?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "At 145 lb/ft³, one US short ton occupies approximately 0.511 cubic yards. Divide short tons by 1.9575 to calculate cubic yards at that density."
      }
    },
    {
      "@type": "Question",
      "name": "Is 2 tons per cubic yard accurate enough?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "At 145 lb/ft³, the exact calculated value is 1.9575 short tons per cubic yard. Rounding it to 2 adds about 2.17%. A different actual density may produce a larger error, so confirm the input first."
      }
    }
  ]
}

